import { and, asc, eq } from "drizzle-orm";
import { getDb, issueDependencies, issues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toIssue } from "./_mappers";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";
import type { IssueDependencyRow } from "@/server/db/schema/issue-dependencies";

function toDependency(row: IssueDependencyRow): IssueDependency {
  return {
    orgId: row.orgId as OrgId,
    issueId: row.issueId as IssueId,
    blockerId: row.blockerId as IssueId,
    createdBy: row.createdBy as UserId,
    createdAt: row.createdAt as IssueDependency["createdAt"],
  };
}

export async function findDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<IssueDependency | null> {
  const row = getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .get();
  return row ? toDependency(row) : null;
}

export async function insertDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
  createdBy: UserId,
): Promise<IssueDependency> {
  const row = getDb()
    .insert(issueDependencies)
    .values({
      orgId,
      issueId,
      blockerId,
      createdBy,
      createdAt: toIsoTimestamp(new Date()),
    })
    .returning()
    .get();
  return toDependency(row);
}

export async function deleteDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const rows = getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .returning()
    .all();
  return rows.length > 0;
}

/** Ids of every issue linked as a blocker of `issueId`, archived or not. */
export async function listBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  return getDb()
    .select({ id: issueDependencies.blockerId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
      ),
    )
    .all()
    .map((row) => row.id as IssueId);
}

/** Ids of every issue that `blockerId` blocks. */
export async function listBlockedIds(
  orgId: OrgId,
  blockerId: IssueId,
): Promise<readonly IssueId[]> {
  return getDb()
    .select({ id: issueDependencies.issueId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .all()
    .map((row) => row.id as IssueId);
}

/** Non-archived blocker issues, by issue number. */
export async function listLiveBlockers(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ issue: issues })
    .from(issueDependencies)
    .innerJoin(issues, eq(issues.id, issueDependencies.blockerId))
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        orgPredicate(issues.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
      ),
    )
    .orderBy(asc(issues.number))
