/**
 * Issue dependencies ("blocked by"): link management, the completion gate and the unblocked notification.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, subscribe, notify
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived, isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { issueResource, requireFound } from "./_support";
import { notify } from "./notification-service";
import type { IssueId, OrgId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { Unsubscribe } from "@/types/event";

/** Raised when an issue cannot be completed because blockers are still open. */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(public readonly blockerIds: readonly IssueId[]) {
    super(`Issue is blocked by open issues: ${blockerIds.join(", ")}`);
    this.name = "IssueBlockedError";
  }
}

function isClosed(issue: Issue): boolean {
  return isArchived(issue) || CLOSED_ISSUE_STATUSES.includes(issue.status);
}

/** Ids of the blockers of `issueId` that are neither archived nor done/canceled. */
export async function findOpenBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const open: IssueId[] = [];
  for (const id of await dependencyRepo.listBlockerIds(orgId, issueId)) {
    const blocker = await issueRepo.findIssueById(orgId, id);
    if (blocker && !isClosed(blocker)) open.push(id);
  }
  return open;
}

async function loadIssue(orgId: OrgId, issueId: IssueId): Promise<Issue> {
  return requireFound(await issueRepo.findIssueById(orgId, issueId), "Issue", issueId);
}

/** True when `target` is reachable from `start` by following blocker links. */
async function reaches(
  orgId: OrgId,
  start: IssueId,
  target: IssueId,
): Promise<boolean> {
  const seen = new Set<IssueId>();
  const stack: IssueId[] = [start];
  while (stack.length > 0) {
    const current = stack.pop() as IssueId;
    if (current === target) return true;
    if (seen.has(current)) continue;
    seen.add(current);
    stack.push(...(await dependencyRepo.listBlockerIds(orgId, current)));
  }
  return false;
}

export async function addBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);
  const issue = await loadIssue(input.orgId, input.issueId);
  const blocker = await loadIssue(input.orgId, input.blockerId);
  assertCan(actor, "issue:update", issueResource(issue));

  if (input.issueId === input.blockerId) {
    throw new Error("An issue cannot block itself");
  }
  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
  if (existing) return existing;

  if (await reaches(input.orgId, input.blockerId, input.issueId)) {
    throw new Error("This dependency would create a cycle");
  }

  return dependencyRepo.insertDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
    actor.userId,
  );
}

export async function removeBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);
  const issue = await loadIssue(input.orgId, input.issueId);
  assertCan(actor, "issue:update", issueResource(issue));
  return dependencyRepo.deleteDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
}

export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);
  const issue = await loadIssue(orgId, issueId);
  assertCan(actor, "issue:read", issueResource(issue));
  return dependencyRepo.listLiveBlockers(orgId, issueId);
}

/** Notifies the assignees of issues whose last open blocker was just closed. */
async function notifyUnblocked(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: Actor["userId"] | null,
): Promise<void> {
  for (const blockedId of await dependencyRepo.listBlockedIds(orgId, blockerId)) {
    const blocked = await issueRepo.findIssueById(orgId, blockedId);
    if (!blocked || isClosed(blocked) || blocked.assigneeId === null) continue;
    if ((await findOpenBlockerIds(orgId, blockedId)).length > 0) continue;

    await notify(orgId, "issue_unblocked", [blocked.assigneeId], {
      title: "An issue was unblocked",
      body: `Issue ${blocked.id} has no open blockers left`,
      href: `/issues/${blocked.id}`,
      actorId,
    });
  }
}

export function registerIssueDependencyListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", async (payload) => {
      const wasClosed = CLOSED_ISSUE_STATUSES.includes(payload.from);
      const nowClosed = CLOSED_ISSUE_STATUSES.includes(payload.to);
      if (wasClosed || !nowClosed) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (!issue || CLOSED_ISSUE_STATUSES.includes(issue.status)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
  ];
  return () => {
    for (const off of offs) off();
  };
}
